insert into public.produk (nama, harga, deskripsi, foto_url, kategori) values
  ('Makanan Kucing Kering Salmon 1 kg', 85000, 'Kibble renyah kaya asam lemak omega-3 untuk bulu berkilau dan sistem imun optimal. Diformulasikan khusus untuk menjaga kesehatan pencernaan kucing dewasa.', '/produk/makanan-kucing.svg', 'Makanan'),
  ('Makanan Basah Tuna 85 g', 18000, 'Potongan daging tuna segar dalam kuah kaldu lezat yang disukai anabul. Membantu memenuhi kebutuhan hidrasi harian kucing kesayangan.', '/produk/makanan-kucing.svg', 'Makanan'),
  ('Makanan Kitten Ayam 1 kg', 95000, 'Nutrisi lengkap dengan protein ayam tinggi kalsium untuk mendukung masa pertumbuhan anak kucing. Tekstur kibble kecil memudahkan anak kucing saat mengunyah.', '/produk/makanan-kucing.svg', 'Makanan'),
  ('Snack Krim Ikan 4 sachet', 25000, 'Camilan cair bertekstur lembut dengan ekstrak ikan murni yang menggugah selera. Praktis disuapkan langsung untuk mempererat bonding dengan kucing.', '/produk/makanan-kucing.svg', 'Makanan'),
  ('Pasir Gumpal Lavender 10 L', 70000, 'Pasir bentonit dengan daya gumpal cepat dan aroma lavender yang menenangkan. Mengunci bau kotoran secara efektif dan minim debu.', '/produk/pasir-kucing.svg', 'Pasir'),
  ('Pasir Tahu Ramah Lingkungan 6 L', 65000, 'Pasir ramah lingkungan dari serat kedelai yang mudah larut dan aman dibuang ke toilet. Lembut di telapak kaki kucing serta bebas debu berbahaya.', '/produk/pasir-kucing.svg', 'Pasir'),
  ('Tongkat Bulu Interaktif', 20000, 'Tongkat lentur dengan rumbai bulu alami dan lonceng kecil yang memicu insting berburu. Sangat efektif untuk melatih kelincahan gerak anabul.', '/produk/mainan-kucing.svg', 'Mainan'),
  ('Bola Lonceng Isi 6', 28000, 'Paket enam bola plastik warna-warni dengan bunyi gemerincing saat bergulir. Membuat kucing tetap aktif dan terhibur saat sendirian di rumah.', '/produk/mainan-kucing.svg', 'Mainan'),
  ('Terowongan Lipat', 55000, 'Terowongan bermain berbahan kanvas tahan cakar yang bisa dilipat saat tidak digunakan. Tempat asyik untuk bermain petak umpet dan beristirahat.', '/produk/mainan-kucing.svg', 'Mainan'),
  ('Cakar Scratcher Kardus', 45000, 'Papan garukan dari kardus daur ulang berdensitas tinggi yang kokoh dan awet. Menjaga kuku kucing tetap sehat sekaligus melindungi furnitur rumah.', '/produk/mainan-kucing.svg', 'Mainan'),
  ('Kasur Bulat Empuk', 110000, 'Kasur bundar dengan bulu halus lembut dan bantalan empuk untuk tidur lebih nyenyak. Memberikan rasa aman dan hangat sepanjang hari.', '/produk/tempat-tidur.svg', 'Tempat tidur'),
  ('Rumah Kucing Kain Lipat', 135000, 'Tenda kucing portabel berdinding tebal yang memberi privasi saat tidur. Mudah dicuci dan dapat dilipat ringkas untuk dibawa bepergian.', '/produk/tempat-tidur.svg', 'Tempat tidur'),
  ('Kalung Lonceng Adjustable', 15000, 'Kalung motif ceria dengan gesper pengaman yang ukurannya bisa diatur sesuai lingkar leher. Dilengkapi lonceng kecil penanda keberadaan kucing.', '/produk/aksesoris-kucing.svg', 'Aksesoris'),
  ('Mangkuk Keramik Anti Tumpah', 48000, 'Wadah makan keramik tebal dengan kemiringan ergonomis untuk mencegah kelelahan kumis. Bagian bawah dilengkapi karet anti slip agar tidak mudah bergeser.', '/produk/aksesoris-kucing.svg', 'Aksesoris'),
  ('Sisir Bulu Kucing', 32000, 'Sisir bergigi rapat dengan ujung membulat yang nyaman untuk mengangkat bulu rontok. Tombol pembersih sekali tekan memudahkan pembuangan bulu terkumpul.', '/produk/grooming-kucing.svg', 'Grooming'),
  ('Gunting Kuku Kucing', 25000, 'Gunting stainless steel dengan mata pisau melengkung khusus untuk kuku anabul. Pegangan anti licin memastikan proses pemotongan kuku lebih aman dan presisi.', '/produk/grooming-kucing.svg', 'Grooming');
